"""Wiki-page API with optimistic locking on a per-row `version` column.

Storage: SQLite. Every page row carries an integer `version` that is bumped
on every successful write. A PUT only applies when the client-supplied
version matches the row's current version; the match check and the bump
happen inside a single conditional UPDATE, so the database (not the app)
decides who wins. Stale writers get 409 with the row's real version.
"""

import sqlite3

from flask import Flask, g, jsonify, request

DATABASE = "wiki.db"

app = Flask(__name__)


# --------------------------------------------------------------------------
# Database helpers
# --------------------------------------------------------------------------

def get_db() -> sqlite3.Connection:
    if "db" not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        # WAL lets concurrent readers work while a write is in flight.
        g.db.execute("PRAGMA journal_mode=WAL")
        g.db.execute("PRAGMA busy_timeout=5000")
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db(db_path: str = DATABASE) -> None:
    conn = sqlite3.connect(db_path)
    try:
        conn.execute("PRAGMA journal_mode=WAL")
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS pages (
                id      INTEGER PRIMARY KEY AUTOINCREMENT,
                title   TEXT NOT NULL,
                body    TEXT NOT NULL DEFAULT '',
                version INTEGER NOT NULL DEFAULT 1
            );
            """
        )
        conn.commit()
    finally:
        conn.close()


def seed_page(title: str = "Home", body: str = "", version: int = 3) -> int:
    """Insert a page at an explicit starting version (handy for tests)."""
    conn = sqlite3.connect(DATABASE)
    try:
        cur = conn.execute(
            "INSERT INTO pages (title, body, version) VALUES (?, ?, ?)",
            (title, body, version),
        )
        conn.commit()
        return cur.lastrowid
    finally:
        conn.close()


# --------------------------------------------------------------------------
# Routes
# --------------------------------------------------------------------------

@app.post("/pages")
def create_page():
    data = request.get_json(silent=True) or {}
    title = str(data.get("title", "")).strip()
    if not title:
        return jsonify({"error": {"code": "validation_error",
                                  "message": "'title' is required"}}), 400
    body = str(data.get("body", ""))
    db = get_db()
    cur = db.execute(
        "INSERT INTO pages (title, body, version) VALUES (?, ?, 1)",
        (title, body),
    )
    db.commit()
    row = db.execute("SELECT * FROM pages WHERE id = ?", (cur.lastrowid,)).fetchone()
    return jsonify(page=_page_dict(row)), 201


@app.get("/pages/<int:page_id>")
def get_page(page_id: int):
    row = _fetch(page_id)
    if row is None:
        return jsonify({"error": {"code": "not_found"}}), 404
    return jsonify(page=_page_dict(row))


@app.put("/pages/<int:page_id>")
def update_page(page_id: int):
    """Conditional single-statement update: the WHERE clause carries the
    optimistic-lock check, so no read-modify-write race exists in SQL."""
    data = request.get_json(silent=True) or {}
    payload = data.get("version", data.get("body"))
    if not isinstance(data.get("version"), int):
        return jsonify({"error": {"code": "validation_error",
                                  "message": "'version' (int) is required"}}), 400
    if not isinstance(data.get("body"), str):
        return jsonify({"error": {"code": "validation_error",
                                  "message": "'body' (str) is required"}}), 400

    new_version = data["version"] + 1
    db = get_db()
    with db:  # transaction; commit on success, rollback on error
        cur = db.execute(
            "UPDATE pages SET body = ?, version = ? WHERE id = ? AND version = ?",
            (data["body"], new_version, page_id, data["version"]),
        )
        if cur.rowcount == 0:
            row = db.execute(
                "SELECT version FROM pages WHERE id = ?", (page_id,)
            ).fetchone()
            if row is None:
                return jsonify({"error": {"code": "not_found"}}), 404
            # Someone else wrote first: report the row's actual version.
            return jsonify({
                "error": {
                    "code": "version_conflict",
                    "current_version": row["version"],
                }
            }), 409
    return jsonify(page={"id": page_id, "version": new_version})


def _fetch(page_id: int):
    return get_db().execute(
        "SELECT * FROM pages WHERE id = ?", (page_id,)
    ).fetchone()


def _page_dict(row) -> dict:
    return {"id": row["id"], "title": row["title"],
            "body": row["body"], "version": row["version"]}


if __name__ == "__main__":
    init_db()
    app.run(debug=True)

